import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { execFileSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
const root = "D:/Packages/PI-Desktop/worktrees/owner-local-control";
const scratch = process.env.PI_SCRATCH_DIR;
assert.ok(scratch);
const destination = join(scratch, "handoff-plugin-lifecycle-candidate.json");
assert.equal(existsSync(destination), false, "Preserve earlier candidate evidence");
const git = (...args) => execFileSync("git", args, { cwd: root, encoding: "utf8" }).trim();
const hash = data => createHash("sha256").update(data).digest("hex");
const paths = ["apps/desktop/electron/main/plugin-runtime.ts", "apps/desktop/electron/main/plugin-loading.ts",
  "apps/desktop/electron/main/plugin-lifecycle.ts", "apps/desktop/electron/main/services/plugin-services.ts",
  "apps/desktop/electron/main/plugin-host-process.mjs", "packages/host-runtime/plugin-host-process.mjs",
  "apps/desktop/electron/main/runtime/handoff-admission.ts", "packages/agent-host/src/maintenance-admission.ts",
  "apps/desktop/test/handoff-plugin-lifecycle.test.mjs", "apps/desktop/test/plugin-lifecycle-user-path.e2e.mjs",
  "apps/desktop/test/helpers/current-source-import-hooks.mjs", "apps/desktop/test/helpers/current-source-vite.mjs",
  "apps/desktop/test/helpers/owner-runtime-import-hooks.mjs", "apps/desktop/test/helpers/ts-import-hooks.mjs"];
const inputs = () => paths.map(path => ({ path, sha256: hash(readFileSync(join(root, path))) }));
assert.equal(git("status", "--porcelain"), "", "Candidate must be clean");
git("merge-base", "--is-ancestor", "origin/main", "HEAD");
const report = { candidate: git("rev-parse", "HEAD"), base: git("rev-parse", "origin/main"),
  branch: git("branch", "--show-current"), dirty: false, startedAt: new Date().toISOString(),
  environment: { platform: process.platform, node: process.version, nodeExecutableSha256: hash(readFileSync(process.execPath)) },
  scope: "Plugin lifecycle admission and original-child process observation; not complete plugin inventory, Electron utility-process or native-family qualification",
  focusedSourceInputs: inputs(), inputCoverage: "Focused source hashes, not a complete dependency or bundled-input manifest",
  checks: [] };
function run(name, file, expected) {
  const args = ["--test", "--test-concurrency=1", "--test-timeout=20000", file];
  const result = spawnSync(process.execPath, args, { cwd: join(root, "apps/desktop"), encoding: "utf8", timeout: 45000,
    env: { ...process.env, TEMP: scratch, TMP: scratch,
      PI_COMMAND_CENTER_DEPENDENCIES: "C:/Users/Administrator/.pi-desktop/scratch/a6fa9016-c24e-432f-8859-b0744dea889d/p0-dependencies" } });
  const check = { name, args, exitCode: result.status, signal: result.signal, stdout: result.stdout ?? "", stderr: result.stderr ?? "" };
  report.checks.push(check);
  assert.equal(result.error, undefined);
  assert.equal(result.status, 0, check.stdout + check.stderr);
  assert.match(check.stdout, new RegExp(`ℹ pass ${expected}\\b`));
  assert.match(check.stdout, /ℹ fail 0\b/);
  assert.match(check.stdout, /ℹ skipped 0\b/);
  return check;
}
try {
  run("deterministic lifecycle regressions", "test/handoff-plugin-lifecycle.test.mjs", 18);
  const native = run("isolated real plugin processes", "test/plugin-lifecycle-user-path.e2e.mjs", 2);
  const diagnostics = native.stdout.split(/\r?\n/).filter(line => line.includes('"originalProcesses"'))
    .map(line => JSON.parse(line.slice(line.indexOf("{"))));
  assert.equal(diagnostics.length, 2);
  assert.equal(diagnostics.reduce((sum, item) => sum + item.originalProcesses, 0), 3);
  assert.ok(diagnostics.every(item => item.originalExitsObserved && item.qualifiedNativeFamilyClosure === false &&
    item.activity.operations === 0 && item.activity.plugins === 0 && item.activity.uncontainedResources > 0));
  report.nativeDiagnostics = diagnostics;
  report.sourceInputsUnchanged = JSON.stringify(inputs()) === JSON.stringify(report.focusedSourceInputs);
  report.endedDirty = git("status", "--porcelain") !== "";
  assert.ok(report.sourceInputsUnchanged && !report.endedDirty);
  report.status = "PASS_WITH_UNQUALIFIED_NATIVE_RESOURCES";
} catch (error) { report.status = "FAIL";report.error = String(error.stack ?? error);process.exitCode = 1; }
report.endedAt = new Date().toISOString();
writeFileSync(destination, JSON.stringify(report, null, 2) + "\n", { flag: "wx" });
console.log(JSON.stringify({ candidate: report.candidate, base: report.base, status: report.status,
  sourceInputsUnchanged: report.sourceInputsUnchanged, endedDirty: report.endedDirty,
  checks: report.checks.map(item => ({ name: item.name, exitCode: item.exitCode })), report: destination }, null, 2));
